-- DF Elements: brochure designs (one page per design, many formats)
-- Run once in the Supabase SQL Editor, after 12_faith_and_inspiration_themes.sql.

-- ============ NEW TABLES ============
create table public.formats (
  key text primary key,
  label text not null,
  group_name text not null,
  product_type text not null references public.product_types(key),
  price numeric(10,2),
  trade_price numeric(10,2),
  cost_item_id bigint references public.cost_items(id) on delete set null,
  sort_order int not null default 0,
  is_active boolean not null default true
);

create table public.designs (
  id bigint generated always as identity primary key,
  code text not null unique,
  name text not null,
  theme_id bigint references public.themes(id) on delete set null,
  language text not null default 'en' check (language in ('af','en','none')),
  wording text not null default '',
  description text not null default '',
  short_description text not null default '',
  gift_for text not null default '',
  image_url text,
  page_url text,
  is_new boolean not null default true,
  is_active boolean not null default true,
  needs_review boolean not null default true,
  review_notes text not null default '',
  sort_order int not null default 0,
  created_at timestamptz not null default now()
);

alter table public.products
  add column design_id bigint references public.designs(id) on delete cascade,
  add column format_key text references public.formats(key) on update cascade;
create index on public.products (design_id);

alter table public.formats enable row level security;
alter table public.designs enable row level security;
create policy "formats read" on public.formats for select using (true);
create policy "formats staff" on public.formats for all to authenticated using (public.is_staff()) with check (public.is_staff());
create policy "designs read" on public.designs for select using (is_active or public.is_staff());
create policy "designs staff" on public.designs for all to authenticated using (public.is_staff()) with check (public.is_staff());

-- ============ NEW THEMES ============

-- ============ COSTING CARDS FOR SMALL ITEMS (estimates, check in Costing) ============
select v.n, v.w, v.h, 'Estimated size, please check', v.s from (values
  ('Key ring', 50, 40, 20), ('Button 30 mm', 30, 30, 21), ('Ruler 30 cm', 320, 40, 22), ('Ruler 15 cm', 170, 40, 23)
) as v(n, w, h, s) where not exists (select 1 from public.cost_items c where c.name = v.n);

